package spotifyclean

import (
	"bytes"
	"encoding/hex"
	"testing"
)

func cipherVector(t *testing.T, value string) []byte {
	t.Helper()
	data, err := hex.DecodeString(value)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func patternedInput(size int) []byte {
	data := make([]byte, size)
	for index := range data {
		data[index] = byte(index * 3)
	}
	return data
}

func TestCipherSequential(t *testing.T) {
	initial := cipherVector(t, "")
	cipher, err := newCipher(initial, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	data := patternedInput(64)
	if err := cipher.decrypt(0, data); err != nil {
		t.Fatal(err)
	}
	expected := cipherVector(t, "3bd34baac741ef271af190dd480e4a2463c9ebbd1c641c0df536e78130f4ab5d9a536252a40c7bb4e18bdc605752e613402d3244d96af6f13d896b1b87cb2556")
	if !bytes.Equal(data, expected) {
		t.Fatalf("output mismatch: got %x, expected %x", data, expected)
	}
	expectedContext := cipherVector(t, "")
	if !bytes.Equal(cipher.context(), expectedContext) {
		t.Fatal("cipher context mismatch after four blocks")
	}
}

func TestCipherPartialBlock(t *testing.T) {
	initial := cipherVector(t, "")
	cipher, err := newCipher(initial, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	data := patternedInput(16)[15:]
	if err := cipher.decrypt(15, data); err != nil {
		t.Fatal(err)
	}
	expected := []byte{cipherVector(t, "3bd34baac741ef271af190dd480e4a2463c9ebbd1c641c0df536e78130f4ab5d9a536252a40c7bb4e18bdc605752e613402d3244d96af6f13d896b1b87cb2556")[15]}
	if !bytes.Equal(data, expected) {
		t.Fatalf("partial block mismatch: got %x, expected %x", data, expected)
	}
	if !bytes.Equal(cipher.context(), initial) {
		t.Fatal("partial block unexpectedly changed the context")
	}
}
